import { clearAlert } from "../../utils/alert";
import { setupCloseButtons, setupDrawer } from "../../utils/drawer";
import { featureFlagEnabled } from "../../utils/featureFlag";
import { sendMessageWithTabId } from "../../utils/message";
import { onDocumentLoaded } from "../../utils/onDocumentLoaded";
import { initSentry } from "../../utils/sentry";
import { getUiConfig } from "../../utils/ui-config";
import { FALLBACK_CONFIG } from "../../utils/ui-config/UI_CONFIG";
import {
  createScorecardV3Script,
  type ScorecardV3Field,
} from "../one-click-scorecard/v3/createScorecardV3Script";
import {
  buildInterviewBaseUrl,
  renderBulletsToHtml,
  renderMarkdownToHtml,
  renderSummarySectionsToHtml,
} from "../one-click-scorecard/v3/structuredNoteRenderers";

let SELECTORS = FALLBACK_CONFIG.gem;

/**
 * Strips whitespace and formatting characters from input text for matching
 */
const transformText = (text: string): string => text.replace(/[\s*]/g, "");

/**
 * Checks if the given text represents the general/overall recommendation field
 */
const isGeneralScorecard = (text: string): boolean => {
  return text === "Overall recommendation";
};

/**
 * Gets the scorecard form container element
 */
export const getScorecardForm = (): HTMLElement | null => {
  let el = document.querySelector<HTMLElement>(SELECTORS.scorecardForm);
  // Fallback for when the scorecard page doesn't have a last form (scorecards tab and CRM pages)
  if (!el) {
    const generalNotesField = getGeneralNotesField();
    el =
      generalNotesField?.editor?.closest<HTMLElement>(
        SELECTORS.scorecardFormFallback,
      ) ?? null;
  }
  return el;
};

type ScorecardField = {
  el: HTMLElement;
  text: string;
  editor: HTMLElement | null;
};

/**
 * Gets all scorecard fields that are visible on the page
 */
const getGemScorecardFields = (): ScorecardField[] => {
  return [
    ...document.querySelectorAll<HTMLElement>(SELECTORS.quillWrapper),
  ].map((el) => {
    const label = el.parentElement?.firstChild as HTMLElement | null;
    return {
      el,
      text: (label?.innerText ?? label?.textContent ?? "")
        .split("\n")[0]
        .trim(),
      editor: el.querySelector<HTMLElement>(".ql-editor"),
    };
  });
};

/**
 * Gets scorecard fields in the V3 adapter format
 */
const getScorecardFields = (): ScorecardV3Field[] => {
  return getGemScorecardFields()
    .filter((field) => !isGeneralScorecard(field.text))
    .map((field) => ({
      text: field.text,
      transformedText: transformText(field.text),
      editor: field.editor,
    }));
};

/**
 * Gets the overall recommendation field as the general notes field
 */
const getGeneralNotesField = (): ScorecardV3Field | null => {
  const generalField = getGemScorecardFields().find((field) =>
    isGeneralScorecard(field.text),
  );
  if (!generalField?.editor) return null;

  return {
    text: generalField.text,
    transformedText: transformText(generalField.text),
    editor: generalField.editor,
  };
};

/**
 * Inserts notes into a Gem Quill editor
 */
const addNotesToField = (editor: HTMLElement, note: string): void => {
  if (editor.classList.contains("ql-blank")) {
    editor.innerHTML = note;
  } else {
    editor.innerHTML += note;
  }
  editor.dispatchEvent(new Event("input", { bubbles: true }));
};

initSentry();

const v3EnabledPromise = Promise.all([
  featureFlagEnabled("autofill-scorecard:v3c"),
  featureFlagEnabled("autofill-scorecard:v3d"),
]).then(([v3c, v3d]) => v3c || v3d);

onDocumentLoaded(() => {
  v3EnabledPromise.then((v3Enabled) => {
    const legacyMode = !v3Enabled;

    const { start, render } = createScorecardV3Script({
      getScorecardFields,
      transformText,
      legacyMode,
      learnMoreUrl: legacyMode
        ? undefined
        : "https://help.brighthire.ai/en/articles/9652919-brighthire-1-click-scorecards-for-gem",

      getGeneralNotesField: () => getGeneralNotesField(),

      getTooltipText: (hasCustomTemplates) =>
        hasCustomTemplates
          ? 'Adds a summary to the "Overall recommendation" field. Choose between your custom AI note template or BrightHire\'s default interview overview.'
          : 'Adds a summary of important interview topics not covered by your scorecard questions to the "Overall recommendation" field.',

      insertUI: (uiContainer) => {
        const form = getScorecardForm();
        if (!form) return;

        form.insertBefore(uiContainer, form.firstElementChild);
      },

      formatting: { mode: "html" },

      addNotesToField,

      // For Gem, we detect scorecard modals via MutationObserver, not URL changes.
      // Return false here so URL changes don't interfere with our DOM-based detection.
      onTabUrlChanged: () => false,

      transformStructuredQuestion: legacyMode
        ? undefined
        : async (item, callId) => {
            const interviewBaseUrl = await buildInterviewBaseUrl(callId);
            return renderBulletsToHtml(item.bullets ?? [], interviewBaseUrl);
          },

      transformStructuredSummary: legacyMode
        ? undefined
        : async (sections, callId) => {
            const interviewBaseUrl = await buildInterviewBaseUrl(callId);
            return renderSummarySectionsToHtml(sections, interviewBaseUrl);
          },

      transformMarkdownSummary: legacyMode
        ? undefined
        : async (markdown, callId) => {
            const interviewBaseUrl = await buildInterviewBaseUrl(callId);
            return renderMarkdownToHtml(markdown, interviewBaseUrl);
          },
    });

    const cleanupScorecardV3 = (): void => {
      document.querySelectorAll(".bh-scorecard-ui").forEach((el) => {
        el.remove();
      });
      clearAlert();
    };

    /**
     * Sets up the scorecard page when the modal is detected.
     * Called by the MutationObserver when a Quill editor appears.
     */
    const setupScorecardPageV3 = async (): Promise<void> => {
      await setupDrawer({
        urlParams: { intent: "Interview" },
      }).then((loading) => {
        if (loading) sendMessageWithTabId({ action: "drawerLoading" });
      });

      render({ disabled: true });
      setupCloseButtons(cleanupScorecardV3);
    };

    /**
     * MutationObserver that watches for Quill editors appearing in the DOM.
     * When a scorecard form is detected, it triggers the V3 UI setup.
     */
    const scorecardModalObserver = new MutationObserver((mutations) => {
      mutations.forEach((mutation) => {
        if (mutation.type === "childList") {
          mutation.addedNodes.forEach(async (node) => {
            if (
              node instanceof HTMLDivElement &&
              node.classList.contains("ql-editor")
            ) {
              const isScorecardModal = !!getGeneralNotesField();
              if (isScorecardModal) {
                await setupScorecardPageV3();
              }
            }
          });
        }
      });
    });

    start();

    getUiConfig("gem").then((uiConfig) => {
      if (uiConfig) {
        SELECTORS = {
          ...FALLBACK_CONFIG.gem,
          ...uiConfig,
        };
      }
      scorecardModalObserver.observe(document.body, {
        childList: true,
        subtree: true,
      });
    });
  });
});
